from dataclasses import dataclass, field

@dataclass
class Point:
    x: int
    y: int = 0

p = Point(3)
print(p)                   # Point(x=3, y=0)
print(p == Point(3, 0))    # True -- compared by field values

@dataclass
class Cart:
    items: list = field(default_factory=list)  # fresh list per instance
